-- 2027 schedule: The American Express (Jan 21) through the week before the FedEx St. Jude.
-- Generated by pga_fantasy/tools/build_results_data.py. Paste into the SQL Editor after schema.sql.
-- Safe to re-run: existing events are updated in place (status is left alone).
-- lock_at = 6:30 AM local time on the first round's day; edit a row if a tee time is earlier.
-- points_multiplier: majors 1.25x, as the 2026 league sheet scored them (Rahm T38 = 23 x 1.25 = 28.75).
on conflict (id) do update set season = excluded.season, name = excluded.name, start_date = excluded.start_date, end_date = excluded.end_date, month = excluded.month, event_type = excluded.event_type, course_name = excluded.course_name, location = excluded.location, lock_at = excluded.lock_at, bonus_label = excluded.bonus_label, points_multiplier = excluded.points_multiplier;
